mapper.select:
SELECT FIN_PRODUCT.FINPROD_NAME as finprodName FROM BOK_POSITION_PRD LEFT JOIN FIN_PRODUCT ON BOK_POSITION_PRD.FINPROD_ID = FIN_PRODUCT.FINPROD_ID AND FIN_PRODUCT.PROFIT_TYPE = #{profitType_01}
LEFT JOIN SYS_ACTIVEREMINDER_SET REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R1S7}
LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID LEFT JOIN PTL_PORTFOLIO_AUTHORITY ON FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID WHERE BOK_POSITION_PRD.CDATE = #{quaryDate}
AND FIN_PRODUCT_ADD.ISSUE_STATUS = '01'
AND BOK_POSITION_PRD.TDY_UNIT_VALUE <1 AND FIN_PRODUCT.FINPROD_TYPE2 = #{finType_F16}
and PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R1S7} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID AND SYS_ACTIVEREMINDER_INFO.CDATE = #{quaryDate} )

with REMINDER_SET as ( SELECT SYS_ACTIVEREMINDER_SET.REM_TYPE, SYS_ACTIVEREMINDER_SET.DAYS as DAYS FROM SYS_ACTIVEREMINDER_SET ) SELECT (
SELECT count(*) FROM FIN_PRODUCT T1 INNER JOIN FIN_CASH_PLAN T2 ON T1.FINPROD_ID = T2.FINPROD_ID AND T1.FINPROD_TYPE2 = T2.FINPROD_TYPE2 left join ( select sum(psp.amount) amount, psp.finprod_id from ptl_sec_position psp where psp.cdate = #{quaryDate} group by psp.finprod_id)pposition on pposition.finprod_id = T1.FINPROD_ID
LEFT JOIN REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R2S1}
inner join data_auth_notify_inst dani on dani.BUSINESS_ID = T1.FINPROD_ID
and dani.institution_code = #{institutionCode}
AND T2.FINPROD_TYPE2 = #{finType_F18} AND pposition.amount > 0 AND T2.MDATE-5 <= #{quaryDate}+REMINDER_SET.DAYS AND T2.MDATE-5 >= #{quaryDate} AND T2.CASH_TYPE in
(#{cashType_01},#{cashType_02},#{cashType_03},#{cashType_04})
AND NOT EXISTS( select 1 from TRD_PRODUCT_DEAL T3
T2.VDATE = T3.VDATE AND T2.MDATE = T3.MDATE AND T2.PAY_DATE = T3.SETTLE_DATE AND T2.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 = #{finType_F18} AND T3.IS_CANCEL = #{noFlag} AND T3.TRADE_STATUS = #{tradeStatus_01} AND T3.PS IN (#{cashType_01},#{cashType_02},#{cashType_03})
)
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R2S1} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T1.FINPROD_MARKET_ID AND SYS_ACTIVEREMINDER_INFO.MDATE = T2.MDATE )
)as R2S1, (
SELECT count(*) FROM FIN_PRODUCT T1 INNER JOIN FIN_CASH_PLAN T2 ON T1.FINPROD_ID = T2.FINPROD_ID AND T1.FINPROD_TYPE2 = T2.FINPROD_TYPE2 left join ( select sum(psp.amount) amount, psp.finprod_id from ptl_sec_position psp where psp.cdate = #{quaryDate} group by psp.finprod_id)pposition on pposition.finprod_id = T1.FINPROD_ID
LEFT JOIN REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R2S2}
inner join data_auth_notify_inst dani on dani.BUSINESS_ID = T1.FINPROD_ID
and dani.institution_code = #{institutionCode}
AND T2.FINPROD_TYPE2 = #{finType_F18} AND pposition.amount > 0 AND add_months(T2.MDATE,-1) <= #{quaryDate}+REMINDER_SET.DAYS AND add_months(T2.MDATE,-1) >= #{quaryDate} AND T2.CASH_TYPE in
(#{cashType_01},#{cashType_02},#{cashType_03},#{cashType_04})
AND NOT EXISTS( select 1 from TRD_PRODUCT_DEAL T3
T2.VDATE = T3.VDATE AND T2.MDATE = T3.MDATE AND T2.PAY_DATE = T3.SETTLE_DATE AND T2.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 = #{finType_F18} AND T3.IS_CANCEL = #{noFlag} AND T3.TRADE_STATUS = #{tradeStatus_01} AND T3.PS IN (#{cashType_01},#{cashType_02},#{cashType_03})
)
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R2S2} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T1.FINPROD_MARKET_ID AND SYS_ACTIVEREMINDER_INFO.MDATE = T2.MDATE )
)as R2S2, (
SELECT count(*) FROM FIN_PRODUCT T1 INNER JOIN FIN_CASH_PLAN T2 ON T1.FINPROD_ID = T2.FINPROD_ID AND T1.FINPROD_TYPE2 = T2.FINPROD_TYPE2 left join ( select sum(psp.amount) amount, psp.finprod_id from ptl_sec_position psp where psp.cdate = #{quaryDate} group by psp.finprod_id)pposition on pposition.finprod_id = T1.FINPROD_ID
LEFT JOIN REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R2S3}
inner join data_auth_notify_inst dani on dani.BUSINESS_ID = T1.FINPROD_ID
and dani.institution_code = #{institutionCode}
AND T2.FINPROD_TYPE2 = #{finType_F18} AND pposition.amount > 0 AND add_months(T2.MDATE,-3) <= #{quaryDate}+REMINDER_SET.DAYS AND add_months(T2.MDATE,-3) >= #{quaryDate} AND T2.CASH_TYPE in
(#{cashType_01},#{cashType_02},#{cashType_03},#{cashType_04})
AND NOT EXISTS( select 1 from TRD_PRODUCT_DEAL T3
T2.VDATE = T3.VDATE AND T2.MDATE = T3.MDATE AND T2.PAY_DATE = T3.SETTLE_DATE AND T2.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 = #{finType_F18} AND T3.IS_CANCEL = #{noFlag} AND T3.TRADE_STATUS = #{tradeStatus_01} AND T3.PS IN (#{cashType_01},#{cashType_02},#{cashType_03})
)
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R2S3} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T1.FINPROD_MARKET_ID AND SYS_ACTIVEREMINDER_INFO.MDATE = T2.MDATE )
)as R2S3, (
SELECT count(*) FROM FIN_PRODUCT T1 INNER JOIN FIN_CASH_PLAN T2 ON T1.FINPROD_ID = T2.FINPROD_ID AND T1.FINPROD_TYPE2 = T2.FINPROD_TYPE2 left join ( select sum(psp.amount) amount, psp.finprod_id from ptl_sec_position psp where psp.cdate = #{quaryDate} group by psp.finprod_id)pposition on pposition.finprod_id = T1.FINPROD_ID
LEFT JOIN REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R2S4}
inner join data_auth_notify_inst dani on dani.BUSINESS_ID = T1.FINPROD_ID
and dani.institution_code = #{institutionCode}
AND T2.FINPROD_TYPE2 = #{finType_F17} AND pposition.amount > 0 AND T2.MDATE-5 <= #{quaryDate}+REMINDER_SET.DAYS AND T2.MDATE-5 >= #{quaryDate} AND T2.CASH_TYPE in
(#{cashType_01},#{cashType_02},#{cashType_03},#{cashType_04})
AND NOT EXISTS( select 1 from TRD_PRODUCT_DEAL T3
T2.MDATE = T3.MDATE AND T2.PAY_DATE = T3.SETTLE_DATE AND T2.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 = #{finType_F17} AND T3.IS_CANCEL = #{noFlag} AND T3.TRADE_STATUS = #{tradeStatus_01} AND T3.PS IN (#{income},#{returnThis},#{maturity},#{ps_T22},#{ps_T23})
)
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R2S4} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T1.FINPROD_MARKET_ID AND SYS_ACTIVEREMINDER_INFO.MDATE = T2.MDATE )
)as R2S4, (
SELECT count(*) FROM FIN_PRODUCT T1 INNER JOIN FIN_CASH_PLAN T2 ON T1.FINPROD_ID = T2.FINPROD_ID AND T1.FINPROD_TYPE2 = T2.FINPROD_TYPE2 left join ( select sum(psp.amount) amount, psp.finprod_id from ptl_sec_position psp where psp.cdate = #{quaryDate} group by psp.finprod_id)pposition on pposition.finprod_id = T1.FINPROD_ID
LEFT JOIN REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R2S5}
inner join data_auth_notify_inst dani on dani.BUSINESS_ID = T1.FINPROD_ID
and dani.institution_code = #{institutionCode}
AND T2.FINPROD_TYPE2 = #{finType_F17} AND pposition.amount > 0 AND add_months(T2.MDATE,-1) <= #{quaryDate}+REMINDER_SET.DAYS AND add_months(T2.MDATE,-1) >= #{quaryDate} AND T2.CASH_TYPE in
(#{cashType_01},#{cashType_02},#{cashType_03},#{cashType_04})
AND NOT EXISTS( select 1 from TRD_PRODUCT_DEAL T3
T2.MDATE = T3.MDATE AND T2.PAY_DATE = T3.SETTLE_DATE AND T2.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 = #{finType_F17} AND T3.IS_CANCEL = #{noFlag} AND T3.TRADE_STATUS = #{tradeStatus_01} AND T3.PS IN (#{income},#{returnThis},#{maturity},#{ps_T22},#{ps_T23})
)
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R2S5} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T1.FINPROD_MARKET_ID AND SYS_ACTIVEREMINDER_INFO.MDATE = T2.MDATE )
)as R2S5, (
SELECT count(*) FROM FIN_PRODUCT T1 INNER JOIN FIN_CASH_PLAN T2 ON T1.FINPROD_ID = T2.FINPROD_ID AND T1.FINPROD_TYPE2 = T2.FINPROD_TYPE2 left join ( select sum(psp.amount) amount, psp.finprod_id from ptl_sec_position psp where psp.cdate = #{quaryDate} group by psp.finprod_id)pposition on pposition.finprod_id = T1.FINPROD_ID
LEFT JOIN REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R2S6}
inner join data_auth_notify_inst dani on dani.BUSINESS_ID = T1.FINPROD_ID
and dani.institution_code = #{institutionCode}
AND T2.FINPROD_TYPE2 = #{finType_F17} AND pposition.amount > 0 AND add_months(T2.MDATE,-3) <= #{quaryDate}+REMINDER_SET.DAYS AND add_months(T2.MDATE,-3) >= #{quaryDate} AND T2.CASH_TYPE in
(#{cashType_01},#{cashType_02},#{cashType_03},#{cashType_04})
AND NOT EXISTS( select 1 from TRD_PRODUCT_DEAL T3
T2.MDATE = T3.MDATE AND T2.PAY_DATE = T3.SETTLE_DATE AND T2.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 = #{finType_F17} AND T3.IS_CANCEL = #{noFlag} AND T3.TRADE_STATUS = #{tradeStatus_01} AND T3.PS IN (#{income},#{returnThis},#{maturity},#{ps_T22},#{ps_T23})
)
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R2S6} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T1.FINPROD_MARKET_ID AND SYS_ACTIVEREMINDER_INFO.MDATE = T2.MDATE )
)as R2S6 FROM DUAL

with REMINDER_SET as ( SELECT SYS_ACTIVEREMINDER_SET.REM_TYPE, SYS_ACTIVEREMINDER_SET.DAYS as DAYS FROM SYS_ACTIVEREMINDER_SET ) SELECT (SELECT count(*) FROM (SELECT distinct '01' VALID_STATUS, T1.FINPROD_TYPE2, T1.FINPROD_ID, T1.PS, T1.CCY, T1.TRADE_DATE, T1.SETTLE_DATE, T1.WORKFLOW_ID, T1.B_TRADE_ID, T2.PORTFOLIO_ID FROM (SELECT * FROM WFL_TRD_PRODUCT_DEAL MINUS SELECT W1.* FROM WFL_TRD_PRODUCT_DEAL W1 INNER JOIN WFL_TRD_PRODUCT_DEAL W2 ON W1.B_TRADE_ID = W2.TRADE_ID WHERE W1.PS = 'T24') T1 LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD T2 ON T1.TRADE_ID = T2.TRADE_ID WHERE (T1.IS_CANCEL is null or T1.IS_CANCEL = #{noFlag}) and T1.TRADE_STATUS = '01') tpd LEFT JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = tpd.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = tpd.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = fp.FINPROD_ID LEFT JOIN SYS_ACTIVEREMINDER_SET T5 on 1 = 1
INNER JOIN DATA_AUTH_NOTIFY_INST dani ON dani.BUSINESS_ID = tpd.PORTFOLIO_ID AND dani.INSTITUTION_CODE = #{institution} AND dani.DATA_TYPE = 'PTL01'
WHERE tpd.FINPROD_TYPE2 = #{fund} AND tpd.PS in ('T24', #{ps_T02}, #{ps_T11}) and fpt.type_6 = #{nonmonetaryFund} AND T5.REM_TYPE = #{R3S1} AND tpd.TRADE_DATE - to_number(T5.DAYS ) <= #{quaryDate} AND tpd.TRADE_DATE >= #{quaryDate} AND NOT EXISTS (SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R3S1} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = fp.FINPROD_ID
and SYS_ACTIVEREMINDER_INFO.INSTITUTION_CODE = #{institutionCode}
) ) as R3S1, (SELECT count(*) FROM (SELECT distinct '01' VALID_STATUS, T1.FINPROD_TYPE2, T1.FINPROD_ID, T1.PS, T1.CCY, T1.TRADE_DATE, T1.SETTLE_DATE, T1.WORKFLOW_ID, T1.B_TRADE_ID, T2.PORTFOLIO_ID FROM (SELECT * FROM WFL_TRD_PRODUCT_DEAL MINUS SELECT W1.* FROM WFL_TRD_PRODUCT_DEAL W1 INNER JOIN WFL_TRD_PRODUCT_DEAL W2 ON W1.B_TRADE_ID = W2.TRADE_ID WHERE W1.PS IN ('T24')) T1 LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD T2 ON T1.TRADE_ID = T2.TRADE_ID WHERE (T1.IS_CANCEL is null or T1.IS_CANCEL = #{noFlag}) and T1.TRADE_STATUS = '01') tpd LEFT JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = tpd.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = tpd.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = fp.FINPROD_ID LEFT JOIN SYS_ACTIVEREMINDER_SET T5 on 1 = 1
INNER JOIN DATA_AUTH_NOTIFY_INST dani ON dani.BUSINESS_ID = tpd.PORTFOLIO_ID AND dani.INSTITUTION_CODE = #{institution} AND dani.DATA_TYPE = 'PTL01'
WHERE tpd.FINPROD_TYPE2 = #{fund} AND tpd.PS in ('T24', #{ps_T02}, #{ps_T11}) and fpt.type_6 = #{monetaryFund} AND T5.REM_TYPE = #{R3S2} AND tpd.TRADE_DATE - to_number(T5.DAYS) <= #{quaryDate} AND tpd.TRADE_DATE >= #{quaryDate} AND NOT EXISTS (SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R3S2} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = fp.FINPROD_ID
and SYS_ACTIVEREMINDER_INFO.INSTITUTION_CODE = #{institutionCode}
) ) as R3S2,
( SELECT count(*) FROM ( SELECT distinct 'R3S3' as remType, fp.FINPROD_ID as assetId, fp.Finprod_Market_Id as assetCode, fp.FINPROD_NAME as assetName, decode(tpd.PS,'T24','回款确认','T02','卖出','T11','现金分红') as reminder, T5.MENU_ID as menuId, T5.URL as url, T5.LABLE as lable, T5.DEALF as dealF, T5.CLOSF as closF, T5.DAYS as days FROM (SELECT distinct '01' VALID_STATUS, T1.FINPROD_TYPE2, T1.FINPROD_ID, T1.PS, T1.CCY, T1.TRADE_DATE, T1.SETTLE_DATE, T1.WORKFLOW_ID, T1.B_TRADE_ID, T2.PORTFOLIO_ID FROM (SELECT * FROM WFL_TRD_PRODUCT_DEAL MINUS SELECT W1.* FROM WFL_TRD_PRODUCT_DEAL W1 INNER JOIN WFL_TRD_PRODUCT_DEAL W2 ON W1.B_TRADE_ID = W2.TRADE_ID WHERE W1.PS = 'T24') T1 LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD T2 ON T1.TRADE_ID = T2.TRADE_ID WHERE (T1.IS_CANCEL is null or T1.IS_CANCEL = #{noFlag}) and T1.TRADE_STATUS = #{tradeStatus_01}) tpd LEFT JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = tpd.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = tpd.FINPROD_ID LEFT JOIN SYS_ACTIVEREMINDER_SET T5 on 1 = 1
inner join data_auth_notify_inst dani99 on dani99.BUSINESS_ID = tpd.PORTFOLIO_ID
and dani99.institution_code in
#{item}
WHERE tpd.FINPROD_TYPE2 = #{finType_F17} AND tpd.PS in ('T24', #{ps_T11}) AND fp.PROFIT_TYPE=#{profitType_01} AND T5.REM_TYPE = #{R3S3} AND tpd.TRADE_DATE - to_number(T5.DAYS) <= #{quaryDate} AND tpd.TRADE_DATE >= #{quaryDate} AND NOT EXISTS (SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R3S3} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = fp.FINPROD_ID) )) as R3S3,
(SELECT COUNT(*) FROM FIN_PRODUCT T1, FIN_CASH_INFO T2, FIN_CASH_PAY_RULE T3, SYS_ACTIVEREMINDER_SET T5 WHERE T1.FINPROD_ID = T2.FINPROD_ID AND T2.CASH_ID = T3.CASH_ID AND T1.FINPROD_TYPE2 = #{fund} /*基金*/ AND T1.PROFIT_TYPE = #{currency} /*货币基金*/ AND T3.PAY_CYCLE = #{paycycle} /*月结*/ AND substr(to_char(#{quaryDate},'yyyy-mm-dd'), 0, 8)||case WHEN t3.day_value < 10 THEN '0'||t3.day_value ELSE t3.day_value END = to_char(#{quaryDate},'yyyy-mm-dd') AND T3.EFF_DATE <= #{quaryDate} AND T5.REM_TYPE = #{R3S4}
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R3S4} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T1.FINPROD_ID
and SYS_ACTIVEREMINDER_INFO.INSTITUTION_CODE = #{institutionCode}
) AND NOT EXISTS (select 1 from TRD_PRODUCT_DEAL T4 where T1.FINPROD_ID = T4.FINPROD_ID AND T4.PS IN (#{ps_T11},#{ps_T12}) AND T4.IS_CANCEL = #{noFlag}) )as R3S4,
(select count(*) from( select distinct temp.* from( select T4.remType,T4.assetCode,T4.assetId,T4.assetName,T4.reminder,T4.mdate, T4.menuId,T4.url,T4.lable,T4.dealF,T4.closF,T4.days from ( SELECT #{R3S10} as remType, T2.FINPROD_MARKET_ID as assetCode, T2.FINPROD_ID as assetId, T2.FINPROD_NAME as assetName, TO_CHAR(T1.MDATE,'yyyy-MM-dd')||'付息还本到期' as reminder, T1.MDATE as mdate, REMINDER_SET.MENU_ID as menuId, REMINDER_SET.URL as url, REMINDER_SET.LABLE as lable, REMINDER_SET.DEALF as dealF, REMINDER_SET.CLOSF as closF, REMINDER_SET.DAYS as days
,T3.PORTFOLIO_ID ,T3.SEC_ACCT_ID ,T3.CDATE FROM PTL_PORTFOLIO pp,PTL_SEC_POSITION T3,FIN_CASH_PLAN T1,FIN_PRODUCT T2/*增加组合权限*/
inner join data_auth_notify_inst dani on dani.BUSINESS_ID = T2.FINPROD_ID
and dani.institution_code = #{institutionCode}
LEFT JOIN SYS_ACTIVEREMINDER_SET REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R3S10}
T1.FINPROD_ID=T2.FINPROD_ID AND T3.FINPROD_ID=T1.FINPROD_ID AND T3.PORTFOLIO_ID = pp.PORTFOLIO_ID and nvl(pp.PARENT_PORTFOLIO_ID,'null') = 'null' AND T3.CDATE < t1.MDATE AND T1.FINPROD_TYPE2=T2.FINPROD_TYPE2 AND T3.AMOUNT > 0 AND T3.HODING_TYPE = '03' AND (T1.INT_AMT > 0 or T1.PRIN_AMT > 0) AND T1.FINPROD_TYPE2=#{finType_F17}
AND ( ( T1.MDATE <= to_date(#{quaryDateStr},'yyyy-mm-dd')+REMINDER_SET.DAYS and to_date(#{quaryDateStr},'yyyy-mm-dd') <= T1.MDATE ) or ( T1.PAY_DATE <= to_date(#{quaryDateStr},'yyyy-mm-dd')+REMINDER_SET.DAYS and to_date(#{quaryDateStr},'yyyy-mm-dd') <= T1.PAY_DATE ) )
AND T1.CASH_TYPE IN (#{cashType_01},#{cashType_02},#{cashType_03}) /*不存在生效的交易*/ and NOT EXISTS (SELECT 1 FROM TRD_FIN_PRODUCT_DEAL_TOTAL TPDA where TPDA.TRADE_STATUS = #{tradeStatus_01} AND TPDA.IS_CANCEL = 'N' and T1.MDATE = TPDA.MDATE AND TPDA.FINPROD_ID = T1.FINPROD_ID AND T3.PORTFOLIO_ID =TPDA.PORTFOLIO_ID AND ((TPDA.CHL_ID is NULL and t3.sec_acct_id='999999') OR TPDA.CHL_ID = T3.SEC_ACCT_ID)) /*不存在流程中的当期或之前的交易*/ AND NOT EXISTS (SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TPDA where TPDA.TRADE_STATUS = #{tradeStatus_01} AND TPDA.IS_CANCEL = 'N' and T1.MDATE >= TPDA.MDATE AND TPDA.FINPROD_ID = T1.FINPROD_ID AND T3.PORTFOLIO_ID =TPDA.PORTFOLIO_ID AND ((TPDA.CHL_ID is NULL and t3.sec_acct_id='999999') OR TPDA.CHL_ID = T3.SEC_ACCT_ID))
)T4
left join PTL_SEC_POSITION tpsp on tpsp.HODING_TYPE = '03' AND tpsp.PORTFOLIO_ID = T4.PORTFOLIO_ID AND tpsp.SEC_ACCT_ID = T4.SEC_ACCT_ID AND tpsp.FINPROD_ID = T4.assetId AND tpsp.CDATE > T4.CDATE AND tpsp.CDATE < t4.mdate left join SYS_ACTIVEREMINDER_INFO on SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R3S10} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = t4.assetCode AND SYS_ACTIVEREMINDER_INFO.MDATE = T4.MDATE inner join PTL_PORTFOLIO_AUTHORITY ppa on T4.PORTFOLIO_ID = T4.PORTFOLIO_ID
and ppa.USER_ID = #{userId}
where tpsp.HODING_TYPE is null AND SYS_ACTIVEREMINDER_INFO.SEQNO IS NULL )temp
left join TRD_PRODUCT_DEAL T3 on temp.assetId = T3.FINPROD_ID and temp.mdate = T3.MDATE AND T3.IS_CANCEL = 'N' AND T3.TRADE_STATUS = #{tradeStatus_01} AND T3.PS IN (#{returnThis},#{ps_T22},#{ps_T23}) where T3.IS_CANCEL IS NULL) )as R3S10,
( SELECT count(*) FROM (SELECT distinct '01' VALID_STATUS, T1.FINPROD_TYPE2, T1.FINPROD_ID, T1.PS, T1.TRADE_DATE, T1.SETTLE_DATE, T1.WORKFLOW_ID, T1.B_TRADE_ID, T2.PORTFOLIO_ID FROM (SELECT * FROM WFL_TRD_PRODUCT_DEAL MINUS SELECT W1.* FROM WFL_TRD_PRODUCT_DEAL W1 INNER JOIN WFL_TRD_PRODUCT_DEAL W2 ON W1.B_TRADE_ID = W2.TRADE_ID WHERE W1.PS = 'T24') T1 LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD T2 ON T1.TRADE_ID = T2.TRADE_ID WHERE (T1.IS_CANCEL is null or T1.IS_CANCEL = #{noFlag}) and T1.TRADE_STATUS = #{tradeStatus_01}) tpd LEFT JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = tpd.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = tpd.FINPROD_ID LEFT JOIN SYS_ACTIVEREMINDER_SET T5 on 1 = 1
inner join data_auth_notify_inst dani99 on dani99.BUSINESS_ID = tpd.PORTFOLIO_ID
and dani99.institution_code in
#{item}
WHERE tpd.FINPROD_TYPE2 = #{finType_F17} AND tpd.PS in ('T24', #{ps_T02}, #{ps_T11}) AND fp.PROFIT_TYPE=#{profitType_03} AND T5.REM_TYPE = #{R3S12} AND tpd.TRADE_DATE - to_number(T5.DAYS) <= #{quaryDate} AND tpd.TRADE_DATE >= #{quaryDate} AND NOT EXISTS (SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R3S12} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = fp.Finprod_Market_Id) )as R3S12 FROM DUAL

SELECT count(*) FROM ( SELECT T2.FINPROD_ID AS assetCode, T2.FINPROD_ABBR AS assetName FROM FIN_CASH_PLAN T1,FIN_PRODUCT T2
T1.FINPROD_ID=T2.FINPROD_ID AND T1.FINPROD_TYPE2=T2.FINPROD_TYPE2 AND T1.FINPROD_TYPE2=#{bond} AND T1.PAY_DATE_UNADJUST-to_number(#{configurationDays}) <= #{quaryDate} AND T1.PAY_DATE_UNADJUST >= #{quaryDate} AND T1.CASH_TYPE IN (#{midIncome},#{midReturn},#{dueRepayment}) AND NOT EXISTS( SELECT 1 FROM TRD_PRODUCT_DEAL T3
T1.VDATE = T3.VDATE AND T1.MDATE = T3.MDATE AND T1.PAY_DATE = T3.SETTLE_DATE AND T1.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 = #{bond} AND T3.IS_CANCEL = #{no} AND T3.PS IN (#{returnThis},#{maturity},#{purchase})
) AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R3S5} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T2.FINPROD_MARKET_ID AND SYS_ACTIVEREMINDER_INFO.MDATE = FIN_CASH_PLAN.PAY_DATE_UNADJUST
and SYS_ACTIVEREMINDER_INFO.INSTITUTION_CODE = #{institutionCode}
)
)

SELECT count(*) FROM ( SELECT T2.FINPROD_ID AS assetCode, T2.FINPROD_ABBR AS assetName FROM FIN_CASH_PLAN T1,FIN_PRODUCT T2
T1.FINPROD_ID=T2.FINPROD_ID AND T1.FINPROD_TYPE2=T2.FINPROD_TYPE2 AND T1.FINPROD_TYPE2=#{projectAssets} AND T1.PAY_DATE_UNADJUST-to_number(#{configurationDays}) <= #{quaryDate} AND T1.PAY_DATE_UNADJUST >= #{quaryDate} AND T1.CASH_TYPE IN (#{midIncome},#{midReturn},#{dueRepayment}) AND NOT EXISTS( SELECT 1 FROM TRD_PRODUCT_DEAL T3
T1.VDATE = T3.VDATE AND T1.MDATE = T3.MDATE AND T1.PAY_DATE = T3.SETTLE_DATE AND T1.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 = #{projectAssets} AND T3.IS_CANCEL = #{no} AND T3.PS IN (#{returnThis},#{maturity},#{purchase})
) AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R3S8} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T2.FINPROD_MARKET_ID AND SYS_ACTIVEREMINDER_INFO.MDATE = FIN_CASH_PLAN.PAY_DATE_UNADJUST
and SYS_ACTIVEREMINDER_INFO.INSTITUTION_CODE = #{institutionCode}
)
)

mapper.sql:
select #{R3S8} as remType, assetCode, assetId, assetName, reminder, menuId, URL, LABLE, DEALF, CLOSF, DAYS, mDate from ( /*流程中*/ SELECT /* 有效状态 */ T2.FINPROD_MARKET_ID AS assetCode, T2.FINPROD_ID assetId, T2.FINPROD_ABBR AS assetName, #{R3S8} as remType, to_char(T1.mdate, 'yyyy-mm-dd') || '付息还本到期' reminder, T5.MENU_ID as menuId, T5.URL, T5.LABLE as lable, T5.DEALF as dealF, T5.CLOSF as closF, T1.mdate AS mDate, T5.DAYS FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN FIN_PRODUCT T2 ON T1.FINPROD_ID = T2.FINPROD_ID left join SYS_ACTIVEREMINDER_SET T5 on T5.REM_TYPE = #{R3S8}
inner join data_auth_notify_inst dani99 on dani99.BUSINESS_ID = T2.FINPROD_ID
and dani99.institution_code in
#{item}
WHERE T1.TRADE_STATUS = #{tradeStatus_01} AND T1.P_TRADE_ID IS NULL /*撤销流程中的数据不展示*/ AND T1.IS_CANCEL = #{noFlag} AND T1.BUSI_TYPE = #{TRD17} AND T1.FINPROD_TYPE2 = #{finType_F18} AND T1.PORTFOLIO_ID IS NULL AND EXISTS (SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL DEAL where DEAL.P_TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID AND DEAL.PORTFOLIO_ID IN (SELECT PORTFOLIO_ID FROM PTL_PORTFOLIO_AUTHORITY WHERE USER_ID = #{userName})) AND T1.MDATE <= #{quaryDate,jdbcType=DATE} + T5.days AND NOT EXISTS (SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R3S8} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T2.FINPROD_ID and SYS_ACTIVEREMINDER_INFO.mdate = T1.mdate ) /*待处理*/ UNION ALL select /* 有效状态 */ T10.FINPROD_MARKET_ID AS assetCode, T10.FINPROD_ID assetId, T10.FINPROD_ABBR AS assetName, #{R3S8} as remType, to_char(T8.mdate, 'yyyy-mm-dd') || '付息还本到期' reminder, T5.MENU_ID as menuId, T5.URL, T5.LABLE as lable, T5.DEALF as dealF, T5.CLOSF as closF, T8.mdate, T5.DAYS from (select T7.FINPROD_ID, T7.AMOUNT QTY, /*这一层，同一组合持仓对不用计划，数量不合并*/ listagg(T7.CASH_TYPE, ',') within group(order by T7.CASH_ID) CASH_TYPE, listagg(T7.CASH_ID, ',') within group(order by T7.CASH_ID) CASH_ID, min(T7.VDATE) VDATE, T7.MDATE, SUM(T7.CASH_AMT * T7.AMOUNT / T7.CASH_BASEAMT) fpriceAmt, max(T7.INT_PRIN_AMT) INT_PRIN_AMT, /*理论本息总额*/ SUM(case T7.CASH_TYPE when '${cashType_01}' then 0 else T7.PRIN_AMT * T7.AMOUNT / T7.CASH_BASEAMT end) prinAmt, /*还本金额*/ SUM(T7.INT_AMT * T7.AMOUNT / T7.CASH_BASEAMT) intAmt, /*理论利息*/ T7.PAY_DATE from (SELECT T1.FINPROD_ID, SUM(T1.AMOUNT) AMOUNT, /*这一层，同一组合持仓对不用计划，数量不合并*/ T6.CASH_TYPE, T6.CASH_ID, T6.VDATE, T6.MDATE, T6.CASH_AMT, t6.INT_PRIN_AMT, T6.PRIN_AMT, T6.CASH_BASEAMT, /*还本金额*/ t6.INT_AMT, /*理论利息*/ t6.PAY_DATE from PTL_SEC_POSITION T1 INNER JOIN (select * from FIN_CASH_PLAN T2 left join SYS_ACTIVEREMINDER_SET T3 on T3.REM_TYPE = #{R3S8} WHERE T2.FINPROD_TYPE2 = #{finType_F18} and T2.CASH_TYPE IN (#{cashType_01},#{cashType_02},#{cashType_03},#{cashType_04}) AND T2.MDATE <= #{quaryDate,jdbcType=DATE} + T3.days and (t2.INT_AMT > 0 or t2.PRIN_AMT > 0)) T6 ON T1.FINPROD_ID = T6.FINPROD_ID AND T1.HODING_TYPE = #{POSITION_TYPE03} AND t1.CDATE < t6.MDATE and T1.AMOUNT > 0 where NOT EXISTS (SELECT 1 FROM PTL_SEC_POSITION PSP WHERE PSP.FINPROD_ID = T1.FINPROD_ID AND PSP.HODING_TYPE = #{POSITION_TYPE03} AND PSP.CDATE > T1.CDATE AND PSP.PORTFOLIO_ID = T1.PORTFOLIO_ID AND PSP.CDATE < T6.MDATE AND PSP.SEC_ACCT_ID = T1.SEC_ACCT_ID) AND NOT EXISTS (SELECT 1 FROM TRD_PRODUCT_DEAL tpd INNER JOIN TRD_PRODUCT_DEAL_ADD TPDA ON tpd.TRADE_ID = tpda.TRADE_ID where tpd.TRADE_STATUS = #{tradeStatus_01} AND tpd.IS_CANCEL = #{noFlag} and T6.CASH_ID = tpd.CASH_ID and T6.MDATE = tpd.MDATE AND TPDA.PORTFOLIO_ID = T1.PORTFOLIO_ID) AND NOT EXISTS (SELECT 1 FROM WFL_TRD_PRODUCT_DEAL tpd INNER JOIN WFL_TRD_PRODUCT_DEAL_ADD TPDA on tpd.TRADE_ID = tpda.TRADE_ID WHERE T6.CASH_ID = tpd.CASH_ID and T6.MDATE = tpd.MDATE AND TPDA.PORTFOLIO_ID = T1.PORTFOLIO_ID) and T1.PORTFOLIO_ID IN (SELECT PORTFOLIO_ID FROM PTL_PORTFOLIO_AUTHORITY WHERE USER_ID = #{userName}) GROUP BY T1.FINPROD_ID, T6.CASH_TYPE, T6.CASH_ID, T6.VDATE, T6.MDATE, T6.CASH_AMT, t6.INT_PRIN_AMT, T6.PRIN_AMT, T6.CASH_BASEAMT, t6.INT_AMT, t6.PAY_DATE) T7 GROUP BY T7.FINPROD_ID, T7.AMOUNT, T7.MDATE, T7.PAY_DATE) T8 LEFT JOIN FIN_PRODUCT T10 ON T10.FINPROD_ID = T8.FINPROD_ID
inner join data_auth_notify_inst dani99 on dani99.BUSINESS_ID = T10.FINPROD_ID
and dani99.institution_code in
#{item}
LEFT JOIN FIN_CASH_CALC_RULE fccr ON instr(t8.CASH_ID, fccr.CASH_ID) > 0 AND fccr.EFF_DATE <= T8.MDATE left join SYS_ACTIVEREMINDER_SET T5 on T5.REM_TYPE = #{R3S8} WHERE NOT EXISTS (SELECT 1 FROM FIN_CASH_CALC_RULE T6 WHERE fccr.CASH_ID = T6.CASH_ID AND T6.EFF_DATE <= T8.MDATE AND T6.EFF_DATE > fccr.EFF_DATE) and T10.FINPROD_TYPE2 = #{finType_F18} AND NOT EXISTS (SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R3S8} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T10.FINPROD_MARKET_ID and SYS_ACTIVEREMINDER_INFO.mdate = T8.mdate ) ) group by assetCode, assetId, assetName, reminder, menuId, URL, LABLE, DEALF, CLOSF, DAYS, mDate

mapper.select:
SELECT count(*) FROM ( SELECT T2.FINPROD_ID AS assetCode, T2.FINPROD_ABBR AS assetName FROM FIN_CASH_PLAN T1,FIN_PRODUCT T2
T1.FINPROD_ID=T2.FINPROD_ID AND T1.FINPROD_TYPE2=T2.FINPROD_TYPE2 AND T1.FINPROD_TYPE2=#{plannedAssets} AND T1.PAY_DATE_UNADJUST-to_number(#{configurationDays}) <= #{quaryDate} AND T1.PAY_DATE_UNADJUST >= #{quaryDate} AND T1.CASH_TYPE IN (#{midIncome},#{midReturn},#{dueRepayment}) AND NOT EXISTS( SELECT 1 FROM TRD_PRODUCT_DEAL T3
T1.VDATE = T3.VDATE AND T1.MDATE = T3.MDATE AND T1.PAY_DATE = T3.SETTLE_DATE AND T1.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 = #{plannedAssets} AND T3.IS_CANCEL = #{no} AND T3.PS IN (#{returnThis},#{maturity},#{purchase})
)
)

SELECT
count(*)
FROM
FIN_EXERCISE_PLAN T1,FIN_PRODUCT T2

	T1.FINPROD_ID = T2.FINPROD_ID
	AND T1.FINPROD_TYPE2 = T2.FINPROD_TYPE2
	AND T1.VDATE-to_number(#{configurationDays}) <= #{quaryDate}
	AND T1.EXERCISE_DATE >= #{quaryDate}
	AND T1.EXERCISE_STATUS = #{unauthorized}

with REMINDER_SET as ( SELECT SYS_ACTIVEREMINDER_SET.REM_TYPE,SYS_ACTIVEREMINDER_SET.DAYS CONFIGURATIONDAYS, #{quaryDate}+SYS_ACTIVEREMINDER_SET.DAYS as DAYS FROM SYS_ACTIVEREMINDER_SET ) SELECT (
SELECT count(*) FROM FIN_EXERCISE_PLAN T1,FIN_PRODUCT T2,REMINDER_SET T3 where T1.FINPROD_ID = T2.FINPROD_ID AND T3.REM_TYPE='R4S1' AND T1.FINPROD_TYPE2 = T2.FINPROD_TYPE2
AND T1.EXERCISE_DATE-T3.CONFIGURATIONDAYS <= #{quaryDate}
AND T1.ACT_EXERCISE_DATE >= #{quaryDate}
AND T1.EXERCISE_STATUS = #{unauthorized}
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R4S1} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T2.FINPROD_ID
and SYS_ACTIVEREMINDER_INFO.INSTITUTION_CODE = #{institutionCode}
) ) as R4S1, (SELECT count(*) FROM INTERF_PAYHSRCSECINFO WIND LEFT JOIN FIN_PRODUCT FIN ON WIND.MARKET = FIN.TRADE_MARKET /*交易场所*/ AND to_char(WIND.VDATE,'yyyy-mm-dd') = to_char(FIN.VDATE,'yyyy-mm-dd') /*起息日*/ AND to_char(WIND.MDATE,'yyyy-mm-dd') = to_char(FIN.MDATE,'yyyy-mm-dd') /*到期日*/ AND WIND.ISSUEAMT = FIN.ISSUE_AMT /*发行金额*/ AND WIND.ISSUERSHORT = FIN.ISSUER /*发行人*/ AND trim(WIND.COUPONSPECIES) = FIN.COUPON_SPECIES /*息票品种*/ LEFT JOIN FIN_TRADE_PRODUCT T ON T.FINPROD_ID = FIN.FINPROD_ID AND WIND.INTERESTRATE = T.INT_TYPE /*利率类型*/ AND WIND.PAPERIR = T.INT_RATE /*初始利率*/ LEFT JOIN Fin_Product_Add A ON A.FINPROD_ID = FIN.FINPROD_ID LEFT JOIN (SELECT SYS_ACTIVEREMINDER_SET.DAYS, SYS_ACTIVEREMINDER_SET.URL, SYS_ACTIVEREMINDER_SET.LABLE, SYS_ACTIVEREMINDER_SET.DEALF, SYS_ACTIVEREMINDER_SET.CLOSF FROM SYS_ACTIVEREMINDER_SET WHERE SYS_ACTIVEREMINDER_SET.REM_TYPE = #{R4S2}) REMINDER_SET ON 1 = 1 WHERE WIND.SECCODE != FIN.FINPROD_MARKET_ID /*'公开市场代码'不同*/
AND WIND.CREATE_TIME - TO_NUMBER(REMINDER_SET.DAYS) <= #{quaryDate} AND WIND.CREATE_TIME >= #{quaryDate} AND FIN.FINPROD_TYPE2 = 'F01' AND A.IS_AUTO_UPDATE='Y' AND NOT EXISTS (SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R4S2} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = FIN.FINPROD_ID
and SYS_ACTIVEREMINDER_INFO.INSTITUTION_CODE = #{institutionCode}
) ) as R4S2 FROM DUAL

SELECT count(decode(A.SUP_STAT,#{R5S1,jdbcType=VARCHAR},A.SUP_STAT)) R5S1, count(decode(A.SUP_STAT,#{R5S2,jdbcType=VARCHAR},A.SUP_STAT,#{R5S3,jdbcType=VARCHAR},A.SUP_STAT)) R5S2 FROM RSK_ISUP_POINT_VAL A INNER JOIN RSK_PORTFOLIO_INDICATOR C ON C.PORTFOLIO_ID = A.PORTFOLIO_ID AND C.IND_ID = A.IND_ID AND NOT EXISTS ( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE (REM_TYPE = 'R5S1' OR REM_TYPE = 'R5S2') AND FINPROD_ID = A.PORTFOLIO_ID AND FINPROD_NAME = A.IND_ID AND REMARK = A.SUP_FREQUENCY AND CDATE = A.SUP_DATE AND EFFFLAG = #{noFlag} ) INNER JOIN RSK_ISUP_INDICATOR B ON B.IND_ID = A.IND_ID LEFT JOIN PTL_PORTFOLIO D ON D.PORTFOLIO_ID = A.PORTFOLIO_ID LEFT JOIN RSK_PORTFOLIO_PACKAGE E ON E.PTL_BAG_ID = A.PORTFOLIO_ID LEFT JOIN (select A.PORTFOLIO_ID AS ID,COUNT(A.SUP_STAT) AS frequency from RSK_ISUP_POINT_VAL A
A.SUP_STAT <> 'NORMAL' AND A.SUP_DATE = #{quaryDate}
group by A.PORTFOLIO_ID) W ON W.ID = A.PORTFOLIO_ID INNER JOIN ( SELECT A.PORTFOLIO_ID, A.IND_ID, A.SUP_DATE, MAX(A.UPDATE_TIME) AS updateTime FROM RSK_ISUP_POINT_VAL A GROUP BY A.PORTFOLIO_ID, A.IND_ID, A.SUP_DATE) M ON A.UPDATE_TIME = M.updateTime AND M.PORTFOLIO_ID = A.PORTFOLIO_ID AND M.IND_ID = A.IND_ID AND M.SUP_DATE = A.SUP_DATE
INNER JOIN DATA_AUTH_NOTIFY_INST dani ON dani.BUSINESS_ID = A.PORTFOLIO_ID
AND dani.INSTITUTION_CODE IN
#{item}
AND dani.MODEL_TYPE = '02' AND dani.DATA_TYPE = 'PTL01'
AND A.SUP_DATE = #{quaryDate}
AND (case when A.SUP_UNITE_STAT is null then A.SUP_STAT else A.SUP_UNITE_STAT end) <> #{infParam, jdbcType=VARCHAR}
ORDER BY A.SUP_DATE DESC

select count(*) R11S1 from(select distinct a.assetCode assetCode, a.assetName assetName, a.remType remType, a.mdate mdate, a.days days, a.menuId menuId, a.url url, a.lable lable, a.dealF dealF, a.closF closF from (
select case when wtpd.trade_id is not null then '04' else '' end paymentStatus, /*缴款状态*/ ee.ENTRUST_STATUS entrustStatus, /*委托状态*/ fp.FINPROD_MARKET_ID assetCode, /*资产代码*/ fp.finprod_name assetName, /*资产名称*/ 'R11S1' remType, to_char(bo.PAY_DATE, 'yyyy-MM-dd') || '_分销缴款' reminder, bo.PAY_DATE mdate, /*缴款日*/ REMINDER_SET.DAYS days, REMINDER_SET.MENU_ID menuId, REMINDER_SET.URL url, REMINDER_SET.LABLE lable, REMINDER_SET.DEALF dealF, REMINDER_SET.CLOSF closF, bobp.ENTRUST_ID entrustId, /*委托编号*/ bobp.BID_ID bidId, /*投标编号*/ ee.portfolio_id portfolioId, /*组合代码*/ pp.portfolio_name portfolioName, /*组合名称*/ fp.FINPROD_ID finprodId, /*资产代码*/ ee.TRADE_MARKET tradeMarket, /*交易场所*/ bo.PAY_TYPE payType, /*缴款方式*/ ebp.bid_prin_amt bidPrinAmt, /*投标券面总额*/ bobp.WIN_PRIN_AMT winPrinAmt, /*中标券面总额*/ bobp.BID_PRICE * 100 bidPrice, /*投标标位%*/ bobp.WIN_PRICE * 100 winPrice, /*中标标位%*/ bo.BID_DATE bidDate, /*投标日*/ bobp.WIN_CPRICE winCprice /*中标净价*/ from BID_ORDER_BID_PRICE bobp left join ETR_ENTRUST ee on bobp.entrust_id = ee.entrust_id left join PTL_PORTFOLIO pp on ee.portfolio_id = pp.portfolio_id left join FIN_PRODUCT fp on fp.FINPROD_ID = ee.finprod_id left join BID_ORDER bo on bo.bid_id = bobp.bid_id LEFT JOIN ETR_ENTRUST_BID_PRICE ebp on ebp.entrust_id = bobp.entrust_id and ebp.BID_PRICE = bobp.BID_PRICE LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD wtpd on wtpd.entrust_id = ebp.entrust_id LEFT JOIN WFL_TRD_PRODUCT_DEAL wtp on wtp.TRADE_ID = wtpd.TRADE_ID LEFT JOIN SYS_ACTIVEREMINDER_SET REMINDER_SET ON REMINDER_SET.REM_TYPE = 'R11S1' where 1 = 1 and bobp.is_win = 'Y' and bo.is_win = bobp.is_win and bobp.WIN_PRICE is not null and wtp.YIELD is not null AND nvl(ee.TRADE_MARKET, fp.TRADE_MARKET) in ('01') union all select bo.PAY_TYPE paymentStatus, /*缴款状态*/ ee.ENTRUST_STATUS entrustStatus, /*委托状态*/ fp.FINPROD_MARKET_ID assetCode, /*资产代码*/ fp.finprod_name assetName, /*资产名称*/ 'R11S1' remType, to_char(bo.PAY_DATE, 'yyyy-MM-dd') || '_分销缴款' reminder, bo.PAY_DATE mdate, /*缴款日*/ REMINDER_SET.DAYS days, REMINDER_SET.MENU_ID menuId, REMINDER_SET.URL url, REMINDER_SET.LABLE lable, REMINDER_SET.DEALF dealF, REMINDER_SET.CLOSF closF, bobp.ENTRUST_ID entrustId, /*委托编号*/ bobp.BID_ID bidId, /*投标编号*/ ee.portfolio_id portfolioId, /*组合代码*/ pp.portfolio_name portfolioName, /*组合名称*/ fp.FINPROD_ID finprodId, /*资产代码*/ ee.TRADE_MARKET tradeMarket, /*交易场所*/ bo.PAY_TYPE payType, /*缴款方式*/ ebp.bid_prin_amt bidPrinAmt, /*投标券面总额*/ bobp.WIN_PRIN_AMT winPrinAmt, /*中标券面总额*/ bobp.BID_PRICE * 100 bidPrice, /*投标标位%*/ bobp.WIN_PRICE * 100 winPrice, /*中标标位%*/ bo.BID_DATE bidDate, /*投标日*/ bobp.WIN_CPRICE winCprice /*中标净价*/ from BID_ORDER_BID_PRICE bobp left join ETR_ENTRUST ee on bobp.entrust_id = ee.entrust_id left join PTL_PORTFOLIO pp on ee.portfolio_id = pp.portfolio_id left join FIN_PRODUCT fp on fp.FINPROD_ID = ee.finprod_id left join BID_ORDER bo on bo.bid_id = bobp.bid_id LEFT JOIN ETR_ENTRUST_BID_PRICE ebp on ebp.entrust_id = bobp.entrust_id and ebp.BID_PRICE = bobp.BID_PRICE LEFT JOIN SYS_ACTIVEREMINDER_SET REMINDER_SET ON REMINDER_SET.REM_TYPE = 'R11S1' where 1 = 1 and bobp.is_win = 'Y' and bo.is_win = bobp.is_win and bobp.TRADE_ID is null AND BOBP.WIN_PRICE IS NOT NULL AND nvl(ee.TRADE_MARKET, fp.TRADE_MARKET) in ('01') minus select bo.PAY_TYPE paymentStatus, /*缴款状态*/ ee.ENTRUST_STATUS entrustStatus, /*委托状态*/ fp.FINPROD_MARKET_ID assetCode, /*资产代码*/ fp.finprod_name assetName, /*资产名称*/ 'R11S1' remType, to_char(bo.PAY_DATE, 'yyyy-MM-dd') || '_分销缴款' reminder, bo.PAY_DATE mdate, /*缴款日*/ REMINDER_SET.DAYS days, REMINDER_SET.MENU_ID menuId, REMINDER_SET.URL url, REMINDER_SET.LABLE lable, REMINDER_SET.DEALF dealF, REMINDER_SET.CLOSF closF, bobp.ENTRUST_ID entrustId, /*委托编号*/ bobp.BID_ID bidId, /*投标编号*/ ee.portfolio_id portfolioId, /*组合代码*/ pp.portfolio_name portfolioName, /*组合名称*/ fp.FINPROD_ID finprodId, /*资产代码*/ ee.TRADE_MARKET tradeMarket, /*交易场所*/ bo.PAY_TYPE payType, /*缴款方式*/ ebp.bid_prin_amt bidPrinAmt, /*投标券面总额*/ bobp.WIN_PRIN_AMT winPrinAmt, /*中标券面总额*/ bobp.BID_PRICE * 100 bidPrice, /*投标