/*流程中*/ SELECT '03' statusValid, T1.TOTLE_TRADE_ID busiCode, T1.PS cashType, T1.PORTFOLIO_ID, T2.PORTFOLIO_NAME, T1.SEC_MANAGE_ACCT_ID, T4.FINPROD_MARKET_ID finprodMarketId, T4.FINPROD_NAME finprodMarketName, /*add by yejiejie 2019-3-27 start*/ T4.FINPROD_ABBR assetName, /*add by yejiejie 2019-3-27 end*/ to_char(T1.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, T1.MDATE mDate/*计息结束日*/, null as DDate, to_char(T1.TRADE_DATE, 'yyyy-MM-dd') TRADE_DATE/*资金到账日*/, T1.SHARE_AMT*100 qty, null PAY_DATE, T3.THEORY_AMT fpriceAmt/*理论本息总额*/, T1.TRADE_AMT/*实收本息总额*/, t3.PA_BUSS_TYPE, T1.FINPROD_ID, T1.WORKFLOW_ID FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID left join SYS_ACTIVEREMINDER_SET REMINDER_SET on REMINDER_SET.REM_TYPE =#{R3S5} WHERE T4.FINPROD_TYPE2 = #{bond} AND T1.P_TRADE_ID IS NULL/*撤销流程中的数据不展示*/ and T1.mdate <= #{quaryDate,jdbcType=DATE} + REMINDER_SET.days AND EXISTS (select 1 from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL DEAL where DEAL.P_TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID and DEAL.PORTFOLIO_ID IN (SELECT PORTFOLIO_ID FROM PTL_PORTFOLIO_AUTHORITY WHERE USER_ID = #{userName})) and NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R3S5} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T4.FINPROD_MARKET_ID and SYS_ACTIVEREMINDER_INFO.mdate = T1.MDATE
and SYS_ACTIVEREMINDER_INFO.INSTITUTION_CODE = #{institutionCode}
)
AND T1.INSTITUTION_CODE IN
#{item}
UNION ALL
/*待处理*/
select '01' statusValid, null busiCode, listagg(t8.CASH_TYPE, ',') within group ( order by t8.CASH_TYPE ) CASH_TYPE, t8.PORTFOLIO_ID, t12.PORTFOLIO_NAME, t8.SEC_ACCT_ID secManageAcctId, t10.FINPROD_MARKET_ID finprodMarketId, t10.FINPROD_NAME finprodMarketName, /*add by yejiejie 2019-3-27 start*/ t10.FINPROD_ABBR assetName, /*add by yejiejie 2019-3-27 end*/ to_char(min(t8.VDATE), 'yyyy-MM-dd') vDate, t8.MDATE mDate, t8.DDATE DDate, null tradeDate, t8.qty*100 qty, to_char(t8.PAY_DATE, 'yyyy-MM-dd') PAY_DATE, ROUND(SUM(t8.fpriceAmt), 2) fpriceAmt, null TRADE_AMT, null PA_BUSS_TYPE, T8.FINPROD_ID, NULL WORKFLOW_ID from ( select T1.FINPROD_ID, SUM(T1.AMOUNT) QTY,/*考虑投资目的数量合并*/ T6.CASH_TYPE, T6.CASH_ID, T6.VDATE,
T6.PAY_DATE as MDATE, T6.MDATE as DDATE, SUM(T6.CASH_AMT * T1.AMOUNT) fpriceAmt,/*理论本息总额*/ case t6.CASH_TYPE when '${cashType_01}' then 0 else ROUND(SUM(T6.PRIN_AMT * T1.AMOUNT), 2) end prinAmt,/*还本金额*/ T1.PORTFOLIO_ID, T1.SEC_ACCT_ID, ROUND(SUM(t6.INT_AMT * T1.AMOUNT), 2) intAmt,/*理论利息*/ t6.PAY_DATE from PTL_SEC_POSITION T1 INNER JOIN ( select * from FIN_CASH_PLAN T2 left join SYS_ACTIVEREMINDER_SET REMINDER_SET on REMINDER_SET.REM_TYPE =#{R3S5} WHERE T2.FINPROD_TYPE2 = #{bond} and T2.CASH_TYPE IN (#{cashType_01},#{cashType_02},#{cashType_03},#{cashType_04})
and T2.PAY_DATE <= #{quaryDate,jdbcType=DATE} + REMINDER_SET.days
) T6 ON T1.FINPROD_ID = T6.FINPROD_ID AND T1.HODING_TYPE = #{POSITION_TYPE03}
AND t1.CDATE < t6.PAY_DATE and T1.AMOUNT > 0
INNER JOIN DATA_AUTH_NOTIFY_INST dani on dani.BUSINESS_ID = T1.PORTFOLIO_ID AND dani.INSTITUTION_CODE=#{institutionCode}
where NOT EXISTS (SELECT 1 FROM PTL_SEC_POSITION PSP WHERE PSP.FINPROD_ID = T1.FINPROD_ID AND PSP.HODING_TYPE = #{POSITION_TYPE03} AND PSP.CDATE > T1.CDATE
AND PSP.CDATE < t6.PAY_DATE AND PSP.PORTFOLIO_ID = T1.PORTFOLIO_ID AND PSP.BRANCH = T1.BRANCH AND PSP.INV_AIM = T1.INV_AIM AND PSP.SEC_ACCT_ID = T1.SEC_ACCT_ID) AND NOT EXISTS (SELECT 1 FROM TRD_PRODUCT_DEAL tpd INNER JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TPDA ON tpd.TOTLE_TRADE_ID = tpda.TOTLE_TRADE_ID where tpd.TRADE_STATUS = #{tradeStatus_01} AND tpd.IS_CANCEL = #{noFlag} and T6.CASH_ID = tpd.CASH_ID
and T6.PAY_DATE = tpd.PAY_DATE AND TPDA.PORTFOLIO_ID = T1.PORTFOLIO_ID AND TPD.SEC_MANAGE_ACCT_ID = T1.SEC_ACCT_ID) AND NOT EXISTS (SELECT 1 FROM WFL_TRD_PRODUCT_DEAL tpd INNER JOIN WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TPDA on tpd.TOTLE_TRADE_ID = tpda.TOTLE_TRADE_ID where T6.CASH_ID = tpd.CASH_ID
and T6.PAY_DATE = tpd.MDATE AND TPDA.PORTFOLIO_ID = T1.PORTFOLIO_ID AND TPD.SEC_MANAGE_ACCT_ID = T1.SEC_ACCT_ID) /*债券存续期待处理 添加过滤条件 TISHKBS-636 add by caojin 2020/6/6 start*/ /*不存在生效的交易*/ AND NOT EXISTS (SELECT 1 FROM TRD_FIN_PRODUCT_DEAL_TOTAL TPDA LEFT JOIN TRD_DEAL_TOTAL_ADD TDTA ON TPDA.TOTLE_TRADE_ID = TDTA.TOTLE_TRADE_ID WHERE TDTA.MP_FINPROD_ID IS NULL AND TPDA.TRADE_STATUS = '01' AND TPDA.BUSI_TYPE = 'TRD10' AND TPDA.IS_CANCEL = 'N' AND T6.MDATE = TPDA.MDATE AND TPDA.FINPROD_ID = T1.FINPROD_ID AND T1.PORTFOLIO_ID =TPDA.PORTFOLIO_ID AND (TPDA.SEC_MANAGE_ACCT_ID = T1.SEC_ACCT_ID OR TPDA.CHL_ID = T1.SEC_ACCT_ID)
AND TPDA.INSTITUTION_CODE = #{institutionCode}
) /*不存在流程中的当期或之前的交易*/ AND NOT EXISTS (SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TPDA LEFT JOIN WFL_TRD_DEAL_TOTAL_ADD TDTA ON TPDA.TOTLE_TRADE_ID = TDTA.TOTLE_TRADE_ID WHERE TDTA.MP_FINPROD_ID IS NULL AND TPDA.TRADE_STATUS = '01' AND TPDA.BUSI_TYPE = 'TRD10' AND TPDA.IS_CANCEL = 'N' AND T6.MDATE >= TPDA.MDATE AND TPDA.FINPROD_ID = T1.FINPROD_ID AND T1.PORTFOLIO_ID =TPDA.PORTFOLIO_ID AND (TPDA.SEC_MANAGE_ACCT_ID = T1.SEC_ACCT_ID OR TPDA.CHL_ID = T1.SEC_ACCT_ID) ) /*债券存续期待处理 添加过滤条件 TISHKBS-636 add by caojin 2020/6/6 end*/ and T1.PORTFOLIO_ID IN (SELECT PORTFOLIO_ID FROM PTL_PORTFOLIO_AUTHORITY
USER_ID = #{userName}
) GROUP BY T1.FINPROD_ID, T6.CASH_TYPE, T6.CASH_ID, T6.VDATE, T6.MDATE, T6.CASH_AMT, T6.PRIN_AMT,/*还本金额*/ T1.PORTFOLIO_ID, T1.SEC_ACCT_ID, t6.INT_AMT, t6.PAY_DATE ) T8 LEFT JOIN FIN_PRODUCT T10 ON T10.FINPROD_ID = T8.FINPROD_ID LEFT JOIN PTL_PORTFOLIO T12 ON T12.PORTFOLIO_ID = T8.PORTFOLIO_ID WHERE T10.FINPROD_TYPE2 = #{bond} and NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R3S5} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T10.FINPROD_MARKET_ID and SYS_ACTIVEREMINDER_INFO.MDATE = t8.MDATE
and SYS_ACTIVEREMINDER_INFO.INSTITUTION_CODE = #{institutionCode}
) GROUP BY t8.PORTFOLIO_ID, t12.PORTFOLIO_NAME, t8.SEC_ACCT_ID, t10.FINPROD_MARKET_ID, t10.FINPROD_NAME, /*add by yejiejie 2019-3-27 start*/ t10.FINPROD_ABBR, /*add by yejiejie 2019-3-27 end*/ t8.MDATE, t8.DDATE, t8.qty, t8.PAY_DATE,T8.FINPROD_ID

