select count(1) R7S3 from ( SELECT DISTINCT #{R7S3} AS remType, fp.finprod_market_id assetCode, fp.Finprod_Abbr assetName, DECODE(fp.manager,NULL,DECODE(fp.sponsor,NULL,DECODE(fp.invest_adviser,NULL,DECODE(fp.issuer,NULL,'融资人','发行人'),'投资顾问'),'担保人'),'管理人') ||'存在声誉风险' AS reminder, mci.CUSTOMER_ID AS orgId, mci.CUSTOMER_NAME AS orgName, sas.MENU_ID AS menuId, sas.URL, sas.LABLE AS lable, sas.DEALF AS dealF, sas.CLOSF AS closF, sas.DAYS FROM FIN_PRODUCT fp LEFT JOIN SYS_ACTIVEREMINDER_SET sas ON 1=1 LEFT JOIN MST_CUSTOMER_INFO mci ON mci.CUSTOMER_ID =DECODE(fp.manager,NULL,DECODE(fp.sponsor,NULL,DECODE(fp.invest_adviser,NULL,DECODE(fp.issuer,NULL,fp.financier,fp.issuer),fp.invest_adviser),fp.sponsor),fp.manager) WHERE sas.REM_TYPE =#{R7S3} AND fp.finprod_type2 IN ('F01','F06','F07','F10','F17','F18') AND mci.Customer_Id IN (select org.orgid from (SELECT DISTINCT orgId FROM (SELECT DISTINCT t2.issuer, t2.financier, t2.manager, t2.sponsor, t2.invest_adviser FROM PTL_SEC_POSITION t1 LEFT JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID = t2.FINPROD_ID WHERE t1.amount != 0
and ( t2.issuer IS NOT NULL OR t2.financier IS NOT NULL OR t2.manager IS NOT NULL OR t2.sponsor IS NOT NULL OR t2.invest_adviser IS NOT NULL ) ) UNPIVOT(orgId FOR NAME IN(issuer, financier, manager, sponsor, invest_adviser)) GROUP BY orgId) org join INF_ORG_NEGATIVE_NEWS t4 on org.orgid = t4.org_no left join MST_CUSTOMER_INFO t5 on org.orgid = t5.customer_id where 1=1 and t4.pub_date <= #{quaryDate}
) AND fp.Finprod_Market_Id not in (SELECT S.FINPROD_ID FROM SYS_ACTIVEREMINDER_INFO S left Join FIN_PRODUCT t2 on S.FINPROD_ID =t2.Finprod_Market_Id WHERE S.REM_TYPE =#{R7S3} AND S.EFFFLAG =#{noFlag} ) AND EXISTS ( SELECT 1 FROM PTL_SEC_POSITION T1 WHERE finprod_id = fp.finprod_id AND amount != 0) )
